// Author: MiYu. Source attack enhancements pay at launch and retain their real weapon damage, missile and target payload.
#include "session.h"
#include <bit>

namespace war3 {
const SpellInfo* ScriptSession::attackOrb(const UnitState& u,const UnitState& target,std::uint32_t forced){
    if(u.illusion || u.abilitiesDisabled())return nullptr;auto consider=[&](std::uint32_t ability,unsigned level)->const SpellInfo*{if(!level || (forced && ability!=forced))return nullptr;bool automatic=u.autocast.contains(ability) && u.autocast.at(ability);if(!forced && !automatic && passiveInfo(ability,level).kind!=PassiveKind::AttackModifier)return nullptr;auto& s=spellInfo(ability,level);if(!attackEnhancement(s.kind) || (!forced && !automatic && !s.passiveAttack) || std::bit_cast<float>(u.mana.bits())<s.mana || spellCooldown(u.handle,ability)>0 || !spellRequirements(u.owner,s))return nullptr;auto available=config_.players[u.owner].abilityAvailable.find(ability);if(available!=config_.players[u.owner].abilityAvailable.end() && !available->second)return nullptr;if((s.kind==SpellKind::ColdArrows || s.kind==SpellKind::BlackArrow) && !arrowTarget(u.owner,target,s))return nullptr;auto slot=weaponFor(u,target);if(!slot)return nullptr;auto weapon=unitWeapon(u,*slot);orbWeapon(weapon,s);return weaponTarget(u,target,weapon)?&s:nullptr;};for(auto [ability,level]:u.abilities)if(level>0)if(auto result=consider(ability,unsigned(level)))return result;if(inventoryFlag(u,"DataC"))for(auto id:u.inventory)if(id && alive(id,NativeKind::Item) && items_.at(id)->holder==u.handle)for(auto ability:itemAbilities(items_.at(id)->type))if(passiveInfo(ability,1).kind==PassiveKind::AttackModifier)if(auto result=consider(ability,1))return result;return nullptr;
}
void ScriptSession::orbWeapon(WeaponDefinition& w,const SpellInfo& s){w.base+=s.amount;if(s.kind!=SpellKind::OrbAnnihilation){w.targets=s.allowed;w.range=s.range;if(w.kind!="normal" && w.kind!="instant"){w.model=s.missile;w.speed=s.speed;w.arc=s.missileArc;w.homing=s.missileHoming;}return;}w.kind="msplash";w.fullArea=s.fullArea;w.halfArea=s.halfArea;w.quarterArea=s.area;w.halfFactor=s.secondary;w.quarterFactor=s.loss;w.targets=s.allowed;w.splashTargets=s.allowed;w.model=s.missile;w.speed=s.speed;w.arc=s.missileArc;w.homing=true;w.range=s.range;}
}
